  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-999', 'C-001');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers rejects unknown intoId', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-001', 'C-999');
  assert.equal(result.ok, false);
  assert.equal(result.error, 'CUSTOMER_NOT_FOUND');
});

test('mergeCustomers removes fromId from customers', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert(!result.value.customers.find((c) => c.id === 'C-001'));
});

test('mergeCustomers keeps intoId in customers', () => {
  const customers = listCustomers();
  const result = mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert(result.value.customers.find((c) => c.id === 'C-002'));
});

test('mergeCustomers reduces customer count by one', () => {
  const customers = listCustomers();
  const beforeCount = customers.length;
  const result = mergeCustomers(customers, [], 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.customers.length, beforeCount - 1);
});

test('mergeCustomers updates invoice customer ids', () => {
  const customers = listCustomers();
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv2 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const invoices = [inv1.value, inv2.value];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-002');
});

test('mergeCustomers does not affect other invoices', () => {
  const customers = listCustomers();
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv2 = createInvoice({
    customerId: 'C-003',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const invoices = [inv1.value, inv2.value];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-003');
});

test('mergeCustomers with multiple invoices from fromId', () => {
  const customers = listCustomers();
  const inv1 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-07',
    lines: [{ sku: 'DES-HOUR', qty: 5 }],
  });
  const inv2 = createInvoice({
    customerId: 'C-001',
    issueDate: '2026-10-08',
    lines: [{ sku: 'DES-HOUR', qty: 3 }],
  });
  const inv3 = createInvoice({
    customerId: 'C-002',
    issueDate: '2026-10-09',
    lines: [{ sku: 'DES-HOUR', qty: 2 }],
  });
  const invoices = [inv1.value, inv2.value, inv3.value];

  const result = mergeCustomers(customers, invoices, 'C-001', 'C-002');
  assert.equal(result.ok, true);
  assert.equal(result.value.invoices[0].customerId, 'C-002');
  assert.equal(result.value.invoices[1].customerId, 'C-002');
  assert.equal(result.value.invoices[2].customerId, 'C-002');
});

test('mergeCustomers does not mutate input customers', () => {
  const customers = listCustomers();
  const originalCount = customers.length;
